select date(coalesce(submitted_time, create_time)) as statDate, count(1) as total
from basket_player_cert_application
where is_delete = 0
  and coalesce(submitted_time, create_time) >= #{startTime}
  and coalesce(submitted_time, create_time) < #{endTime}
group by date(coalesce(submitted_time, create_time))

select date(create_time) as statDate, count(1) as total
from basket_team
where is_delete = 0
  and create_time >= #{startTime}
  and create_time < #{endTime}
group by date(create_time)

select date(coalesce(submit_time, create_time)) as statDate, count(1) as total
